var html=result,
header={"Referer":baseUrl};
(function getImgList(){
    var p = "picdata = \\[(.*?)\\];";
    var p1 = "imgDomain = \\'(.*?)\\';";
    var path = html.match(p)[1].replace(/\"/g, "").replace(/\\/g, "").split(",");
    var imgDomain = html.match(p1)[1];
    var piclist = new Array([path.length]);
    for (var i = 0; i < path.length; i++) {
        piclist[i] = imgDomain + path[i];
    }
    return piclist;
}()).map(uri=>
'<img src="'+uri+"," + JSON.stringify(header)+'">').join("\n")

ruleBookInfo.init:
@js:
(function(){
    let doc = org.jsoup.Jsoup.parse(result)
    let og = (selector) => doc.select('[property="og:' + selector + '"]').attr('content')
    return {
        name: og('novel:book_name'),
        author: og('novel:author'),
        kind: og('novel:category')
        +'•'+og('novel:status')
        +'•'+String(og('novel:update_time')),
        latest: og('novel:latest_chapter_name'),
        cover: og('image'),
        intro: og('description'),
        url:og('novel:read_url')
    }
})()

